import type { MachineEntry } from "@/pipeline/schema";

/**
 * Server-side answer resolution (PRD §7.3): the answer never leaves the
 * server until the game ends.
 *
 * - Daily: looked up in Supabase `daily_answers` (pre-generated by
 *   generate_daily_answers()). Falls back to a deterministic hash pick when
 *   the database is unreachable, so local dev and outages keep the same
 *   answer for everyone on a given date.
 * - Endless: seeded random pick from the pool; the seed is generated by the
 *   client, the answer never travels to it.
 */

// ---------------------------------------------------------------- seeding --

function hashString(s: string): number {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function seededPick<T>(items: readonly T[], seed: string): T {
  if (items.length === 0) throw new Error("empty pool");
  const rng = mulberry32(hashString(seed));
  return items[Math.floor(rng() * items.length)];
}

// ------------------------------------------------------------- daily pool --

export function dailyPool(
  entries: readonly MachineEntry[],
  difficulty: "easy" | "hard",
): MachineEntry[] {
  return difficulty === "easy" ? entries.filter((e) => e.difficulty === "easy") : [...entries];
}

/** Deterministic fallback pick (also used when the DB row is missing). */
export function fallbackDailyAnswerId(
  entries: readonly MachineEntry[],
  datasetKey: string,
  difficulty: "easy" | "hard",
  date: string,
): string {
  const pool = dailyPool(entries, difficulty);
  if (pool.length === 0) throw new Error(`empty ${difficulty} pool for ${datasetKey}`);
  return seededPick(pool, `${datasetKey}:${difficulty}:${date}`).id;
}

// --------------------------------------------------------- Supabase lookup --

async function supabaseRpc(path: string, params: URLSearchParams): Promise<unknown | null> {
  const url = process.env.NEXT_PUBLIC_SUPABASE_URL;
  const key = process.env.SUPABASE_SECRET_KEY ?? process.env.SUPABASE_SERVICE_ROLE_KEY;
  if (!url || !key) return null;
  const res = await fetch(`${url}/rest/v1/${path}?${params.toString()}`, {
    headers: {
      apikey: key,
      Authorization: `Bearer ${key}`,
      Accept: "application/json",
    },
    // Answers are fixed per date; a short revalidate keeps isolates cheap
    // without ever serving yesterday's pick after midnight.
    next: { revalidate: 60 },
  });
  if (!res.ok) return null;
  return res.json();
}

/**
 * Resolve the daily answer id for (dataset, difficulty, date).
 * DB first, deterministic fallback second — never throws for network issues.
 */
export async function getDailyAnswerId(
  entries: readonly MachineEntry[],
  datasetKey: string,
  difficulty: "easy" | "hard",
  date: string,
): Promise<{ id: string; source: "db" | "fallback" }> {
  try {
    const rows = (await supabaseRpc(
      "daily_answers",
      new URLSearchParams({
        select: "entry_id",
        date: `eq.${date}`,
        dataset: `eq.${datasetKey}`,
        difficulty: `eq.${difficulty}`,
        limit: "1",
      }),
    )) as { entry_id: string }[] | null;
    if (rows && rows.length > 0 && rows[0].entry_id) {
      return { id: rows[0].entry_id, source: "db" };
    }
  } catch {
    // fall through to deterministic pick
  }
  return { id: fallbackDailyAnswerId(entries, datasetKey, difficulty, date), source: "fallback" };
}

/** Endless answer id — derived from the client seed, never stored. */
export function getEndlessAnswerId(
  entries: readonly MachineEntry[],
  datasetKey: string,
  difficulty: "easy" | "hard",
  seed: string,
): string {
  const pool = dailyPool(entries, difficulty);
  if (pool.length === 0) throw new Error(`empty ${difficulty} pool for ${datasetKey}`);
  return seededPick(pool, `${datasetKey}:${difficulty}:endless:${seed}`).id;
}

// ------------------------------------------------------------------- hints --

export interface HintPayload {
  /** Machine image URL (hint 1 — a picture is the whole hint). */
  image?: string;
  /** Human-readable hint text (hint 2). */
  text?: string;
}

function httpsUrl(url: string): string {
  return url.startsWith("//") ? `https:${url}` : url;
}

/** Hint 1 (index 0): the machine's image only. Hint 2 (index 1): first letter + length. */
export function machineHint(entry: MachineEntry, index: 0 | 1): HintPayload {
  if (index === 0) {
    return entry.image
      ? { image: httpsUrl(entry.image) }
      : { text: "No image on the wiki for this one." };
  }
  const first = entry.name[0]?.toUpperCase() ?? "?";
  return { text: `Starts with "${first}" — ${entry.name.replace(/\s/g, "").length} characters.` };
}
